function bestClosingHour(log: string): number {
  const n = log.length;
  let best = Infinity, bestHour = 0;
  for (let j = 0; j <= n; j++) {
    let pen = 0;
    for (let h = 0; h < n; h++) {
      if (h < j && log[h] === "N") pen++;
      if (h >= j && log[h] === "Y") pen++;
    }
    if (pen < best) { best = pen; bestHour = j; }
  }
  return bestHour;
}

