function bestClosingHour(log: string): number {
  let yAhead = 0;
  for (const c of log) if (c === "Y") yAhead++;
  let nBefore = 0, best = yAhead, bestHour = 0;
  for (let h = 0; h < log.length; h++) {
    if (log[h] === "Y") yAhead--; else nBefore++;
    if (nBefore + yAhead < best) { best = nBefore + yAhead; bestHour = h + 1; }
  }
  return bestHour;
}

